import hashlib,json,platform,re,resource,subprocess,time
from pathlib import Path
from hmt_rnd.voice_adapter import transcribe
from hmt_rnd.voice_models import LocalVoiceConfig,TranscriptionRequest
from hmt_rnd.voice_process import run_local
root=Path(__file__).resolve().parent
plan=json.loads((root/'predeclared_plan.json').read_text())
modelpin=json.loads((root/'model_pin.json').read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
exe=root/'build/bin/whisper-cli';model=root/'models/ggml-base.en.bin';wrapper=root/'no_network'
config=LocalVoiceConfig(executable=exe,executable_sha256=sha(exe),model=model,model_sha256=modelpin['sha256'],audio_root=root/'samples',timeout_seconds=30.0,max_audio_seconds=30.0,max_asset_bytes=200*1024*1024,threads=2)
request=TranscriptionRequest(audio=root/'samples/jfk.wav',selected_provider='whisper.cpp')
guards=[];commands=[]
def guard(request):
 guards.append({'selected_provider':request.selected_provider,'decision':'ADMITTED','authority':'Synthetic host-trusted admission for public test sample only'})
 return 'ADMITTED'
def runner(command,timeout,limit):
 commands.append({'argv':[str(wrapper)]+command,'timeout':timeout,'max_output_bytes':limit})
 return run_local([str(wrapper)]+command,timeout,limit)
probe=subprocess.run([str(wrapper),'--probe'],text=True,capture_output=True,timeout=5)
assert probe.returncode==0 and probe.stdout.strip()=='SOCKET_DENIED_EPERM'
before=resource.getrusage(resource.RUSAGE_CHILDREN);start=time.monotonic()
try:
 draft=transcribe(request,config,guard=guard,runner=runner)
 result={'status':'TRANSCRIPTION_OBSERVED','draft':draft.model_dump(mode='json')}
except Exception as e:
 result={'status':'INFERENCE_FAILED','exception_type':type(e).__name__,'exception':str(e)}
elapsed=time.monotonic()-start;after=resource.getrusage(resource.RUSAGE_CHILDREN)
result.update({'predeclared_plan':plan,'model_pin':modelpin,'executable_sha256':sha(exe),'executable_bytes':exe.stat().st_size,'seccomp_wrapper_sha256':sha(wrapper),'seccomp_source_sha256':sha(root/'no_network.c'),'seccomp_source':(root/'no_network.c').read_text(),'seccomp_probe':{'returncode':probe.returncode,'stdout':probe.stdout,'stderr':probe.stderr},'network_scope':'socket/connect/sendto/sendmsg denied by inherited seccomp filter on native x86_64. Parent voice runner closes unrelated descriptors. Namespace isolation unavailable (EPERM); not a general adversarial sandbox/packet trace.','guard_observations':guards,'commands':commands,'elapsed_seconds':elapsed,'child_user_seconds_delta':after.ru_utime-before.ru_utime,'child_system_seconds_delta':after.ru_stime-before.ru_stime,'largest_child_peak_rss_kib':after.ru_maxrss,'peak_rss_scope':'Largest child in this driver; probe child was tiny, inference child dominates; excludes Python parent.','platform':platform.platform(),'python':platform.python_version(),'cpu_model':next((line.split(':',1)[1].strip() for line in Path('/proc/cpuinfo').read_text().splitlines() if line.startswith('model name')),'unknown')})
if result['status']=='TRANSCRIPTION_OBSERVED':
 reference=re.findall(r"[a-z]+",plan['expected_reference'].lower());actual=re.findall(r"[a-z]+",draft.text.lower())
 dp=list(range(len(actual)+1))
 for i,w in enumerate(reference,1):
  nxt=[i]
  for j,a in enumerate(actual,1):nxt.append(min(nxt[-1]+1,dp[j]+1,dp[j-1]+(w!=a)))
  dp=nxt
 result['comparison']={'reference_word_count':len(reference),'actual_word_count':len(actual),'word_errors':dp[-1],'word_error_rate':dp[-1]/len(reference),'normalized_exact_match':actual==reference,'note':'One public sample; not technical corpus, noise, speaker, or userhardware qualification.'}
(root/'live_result.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:result[k] for k in ('status','elapsed_seconds','largest_child_peak_rss_kib')}))
if 'draft' in result:print(result['draft']['text']);print(result['comparison'])

